    def test_actual_incomplete_failure_and_prior_layer_cannot_pass(self):
        for name in ('wire-budget-failure','net-board'):
            with self.assertRaises(ValueError):require(json.loads((HERE/'reports'/name/'assessment.json').read_text()))
    def test_capture_only_adds_gate_and_resource_limit(self):
        s=(HERE/'memory_operational_capture.py').read_text().replace('\nfrom parameter_recovery_gate import require','').replace('require(prior);','').replace('logical_limit=80*1024**3','logical_limit=4*1024**3')
        self.assertEqual(ast.dump(ast.parse(s)),ast.dump(ast.parse((HERE/'memory_fault_capture.py').read_text())))

    def test_memory_budget_receipts_remain_bounded(self):
        with tempfile.TemporaryDirectory() as tmp:
            root=Path(tmp);r=dict(completed=True,startupOnly=False,captureTimeoutSeconds=3300,log=dict(bytes=100,compressedBytes=4,logicalLimitBytes=80*1024**3,compressedLimitBytes=256*1024**2))
            for mode in ('off','observe','callback-list-user-corrupt','callback-list-object-corrupt','callback-list-function-corrupt','callback-list-link-corrupt')+tuple('memory-'+n+'-corrupt' for n in ('name','name-pointer','cache-pointer','port-head','storage-pointer')):
                folder=root/mode;folder.mkdir();(folder/'ngspice.log.xz').write_bytes(b'test');(folder/'run.json').write_text(json.dumps(r))
            self.assertEqual(len(budgets(root)),11)
            for mutate in (lambda d:d.update(completed=False),lambda d:d.update(startupOnly=True),lambda d:d.update(captureTimeoutSeconds=4000),lambda d:d['log'].update(bytes=81*1024**3),lambda d:d['log'].update(compressedBytes=3),lambda d:d['log'].update(logicalLimitBytes=128*1024**3)):
                bad=copy.deepcopy(r);mutate(bad);(root/'observe/run.json').write_text(json.dumps(bad))
                with self.assertRaises(ValueError):budgets(root)

